      LK('agree', 'ES', [['b17', 0, T('Қиын жағдайда сабырлы бола аламын.', 'Я умею сохранять спокойствие в трудной ситуации.', 'I can stay calm in difficult situations.')], ['b18', 0, T('Сәтсіздіктен кейін тез есімді жиямын.', 'После неудачи я быстро прихожу в себя.', 'I recover quickly after a setback.')], ['b19', 1, T('Ұсақ нәрселерге жиі уайымдаймын.', 'Я часто переживаю из-за мелочей.', 'I often worry about small things.')], ['b20', 1, T('Сын айтылса, көңіл-күйім ұзақ уақыт түсіп жүреді.', 'Критика надолго портит мне настроение.', 'Criticism stays with me and lowers my mood for a long time.')]])
